import {openDialog,closeDialog,ownsDialog,environment,jsonRequest} from './ui-core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let sharedSession=null,authEpoch=0;
let key='',connections=[],selected='',epoch=0,offset=0,detailEpoch=0,canManage=false,pendingSetups=[],createPending=false;
const kind={usage:'模型调用',error:'请求失败',tool_start:'调用前检查',tool:'工具调用',child:'子任务完成',session:'会话开始',transport:'请求状态'};
const amount=n=>'¥'+Number(n||0).toFixed(4);
export function codingPage(){return '<section id="coding-root" aria-label="编码工具接入"></section>'}
export function clearCodingSession(){authEpoch++;sharedSession=null;key='';connections=[];selected='';pendingSetups=[];canManage=false;epoch++;detailEpoch++;}
export function bindCoding(shared=null){sharedSession=shared;if(shared)key=shared.key;const root=document.querySelector('#coding-root');if(root)mount(root)}
async function api(path,data,method='POST'){return jsonRequest(path,{method:data===undefined?'GET':method,headers:{authorization:'Bearer '+key,'content-type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),cache:'no-store'},'此站点仅提供前端预览。请在本机或私有部署的 AgentGuard 服务中连接。')}
function mount(root){const ticket=++epoch;root.innerHTML=`<div class="heading"><div><h1>编码工具</h1><p>Claude Code 与 Codex 的用量、工具活动和运行保护。</p></div><a class="button" href="CODING.html" target="_blank" rel="noopener">接入文档 ↗</a></div><div class="coding-intro"><section class="card"><span class="coding-step">01 / 只监测</span><h2>先看清每次调用</h2><p>接收遥测，按模型、项目和客户归集。检测异常并告警，不控制客户端进程。</p></section><section class="card"><span class="coding-step">02 / 本机托管</span><h2>给运行加上边界</h2><p>通过启动器运行非交互任务。触发预算、风险或遥测断连时，停止该启动器创建的进程组。</p></section></div><div class="note">遥测有延迟，不能保证费用不超额。Claude 上报费用和按单价计算的费用均为估算，不是订阅账单。缺少参数或父子关系时，检测覆盖会明确标注。</div><div id="coding-auth"></div><div id="coding-message" role="status" aria-live="polite"></div><div id="coding-receipts"></div><div id="coding-content"></div>`;
 const $=s=>root.querySelector(s);environment(key?'编码工具 · 正在校验':'编码工具 · 未连接','连接真实服务后读取遥测记录');
 if(!key){$('#coding-auth').innerHTML='<form id="coding-login" class="usage-login"><label>服务端访问密钥<input name="key" type="password" autocomplete="off" required placeholder="READ_KEY 或 ADMIN_KEY"></label><button class="button primary">连接服务端</button><small>只读密钥可查看记录；创建连接、停止与审批需管理员密钥。凭证只保存在页面内存。</small></form>';$('#coding-login').onsubmit=e=>{e.preventDefault();key=new FormData(e.target).get('key');mount(root)};return}
 $('#coding-auth').innerHTML='<div class="usage-toolbar"><span>同源连接 · 凭证仅在内存</span><div class="actions"><button class="button" data-coding-refresh>刷新</button><button class="button" data-coding-disconnect>断开连接</button></div></div>';
 $('[data-coding-refresh]').onclick=()=>mount(root);$('[data-coding-disconnect]').onclick=()=>{if(sharedSession)return sharedSession.onLogout();key='';connections=[];selected='';pendingSetups=[];mount(root)};
 renderReceipts(root);$('#coding-content').innerHTML='<div class="empty">正在读取连接…</div>';
 api('/api/coding/connections').then(d=>{if(ticket!==epoch||!root.isConnected)return;connections=d.connections;canManage=d.canManage===true;environment(canManage?'编码工具 · 管理员':'编码工具 · 只读','已验证 · 真实遥测连接');if(!connections.some(c=>c.id===selected)){selected=connections[0]?.id||'';offset=0}renderConnections(root,ticket)}).catch(e=>{if(ticket===epoch&&root.isConnected){environment('编码工具 · 连接失败','请检查密钥和服务状态');$('#coding-message').textContent=e.message;$('#coding-content').innerHTML='<div class="empty">未连接真实服务，没有加载示例用量。</div>'}})
}
function renderConnections(root,ticket){const $=s=>root.querySelector(s);$('#coding-content').innerHTML=`<div class="section-title">连接与保护</div><div class="coding-connections">${connections.map(c=>{const cost=c.tasks.reduce((s,t)=>s+t.cost,0),risk=c.tasks.reduce((s,t)=>s+t.alerts.length,0);return `<section class="card coding-connection"><div class="coding-card-head"><div><h2>${esc(c.name)}</h2><small>${c.source==='codex'?'Codex':'Claude Code'} · ${esc(c.project)}</small></div><span class="badge ${c.mode==='managed'?'running':''}">${c.mode==='managed'?'本机托管':'只监测'}</span></div><div class="coding-total">${amount(cost)}<small>已知估算费用</small></div><dl class="coding-meta"><dt>运行状态</dt><dd>${!c.enabled?'凭证已撤销':c.mode==='monitor'?'仅监测，不拦截':c.controller_live?'启动器在线':c.controller?.state==='stopped'?'启动器确认已停止':c.controller?.state==='completed'?'启动器确认已完成':c.controller?.state==='failed'?'启动器确认失败':'启动器离线 / 未启动'}</dd><dt>收到遥测</dt><dd>${c.received} 条 · ${risk} 条告警</dd><dt>最近接收</dt><dd>${c.last_received?esc(new Date(c.last_received).toLocaleString('zh-CN')):'尚未收到'}</dd></dl><div class="actions"><button class="button ${c.id===selected?'primary':''}" data-coding-select="${c.id}">查看活动</button><button class="button" data-coding-setup="${c.id}">接入配置</button>${c.enabled&&canManage?`<button class="button" data-coding-action="revoke" data-id="${c.id}">撤销连接</button>${c.mode==='managed'?`<button class="button" data-coding-action="stop" data-id="${c.id}">请求停止</button>`:''}`:''}</div></section>`}).join('')||'<div class="card empty">尚未创建连接。先配置一个编码工具，再在本机启用遥测。</div>'}</div>${canManage?'<details class="card coding-create"><summary>＋ 新建连接（管理员）</summary>'+createForm()+'</details>':'<div class="note">只读连接：创建、审批、导入和停止操作需要断开后使用 ADMIN_KEY 连接。</div>'}<section id="coding-detail"></section>`;
 root.querySelectorAll('[data-coding-select]').forEach(b=>b.onclick=()=>{selected=b.dataset.codingSelect;offset=0;renderConnections(root,ticket)});
 root.querySelectorAll('[data-coding-setup]').forEach(b=>b.onclick=()=>setup(connections.find(c=>c.id===b.dataset.codingSetup)));
 root.querySelectorAll('[data-coding-action]').forEach(b=>b.onclick=()=>confirmAction(root,b.dataset.id,b.dataset.codingAction));
 if(canManage)$('#coding-create-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type="submit"]');if(button.disabled||createPending)return;createPending=true;button.disabled=true;const requestKey=key,requestAuthEpoch=authEpoch;try{const f=new FormData(e.target),prices={},model=f.get('model').trim();if(model&&['input','output','cached','creation'].some(k=>!f.get(k).trim()))throw Error('填写模型时需同时填写四项单价；无缓存写入计费可填 0');if(model)prices[model]={input:Number(f.get('input')),output:Number(f.get('output')),cached:Number(f.get('cached')),creation:Number(f.get('creation'))};const created=await api('/api/coding/connections',{name:f.get('name'),source:f.get('source'),mode:f.get('mode'),policy:f.get('policy'),action:f.get('action'),budget:Number(f.get('budget')),usdToCny:f.get('fx')||null,customer:f.get('customer'),feature:f.get('feature'),project:f.get('project'),prices});if(requestKey!==key||requestAuthEpoch!==authEpoch)return;pendingSetups.push(created);if(ticket!==epoch||!root.isConnected){renderReceipts(document.querySelector('#coding-root'));return}selected=created.id;offset=0;mount(root);if(!document.querySelector('#modal').open){setup(created,created.token);renderReceipts(root)}}catch(err){if(ticket===epoch&&root.isConnected)$('#coding-message').textContent=err.message}finally{createPending=false;button.disabled=false;const current=document.querySelector('#coding-root #coding-create-form button[type="submit"]');if(current)current.disabled=false}};
 if(selected)detail(root,ticket,selected);
}
function createForm(){return `<form id="coding-create-form"><div class="usage-fields"><label>连接名称<input name="name" required maxlength="100" placeholder="AICost 开发"></label><label>编码工具<select name="source"><option value="claude-code">Claude Code</option><option value="codex">Codex</option></select></label><label>模式<select name="mode"><option value="monitor">只监测</option><option value="managed">本机托管</option></select></label><label>项目<input name="project" placeholder="AICost"></label><label>客户<input name="customer" placeholder="内部研发"></label><label>功能<input name="feature" placeholder="代码开发"></label><label>费用策略<select name="policy"><option value="research">研究智能体</option><option value="support">客服智能体</option><option value="content">内容智能体</option></select></label><label>每会话预算（元）<input name="budget" type="number" min="0.001" step="any" value="10" required></label><label>触发后处理<select name="action"><option value="stop">请求停止</option><option value="approve">转人工确认</option></select></label><label>USD → CNY 汇率<input name="fx" type="number" min="0.001" step="any" placeholder="自行填写，无默认汇率"></label></div><p class="usage-caption">只监测按会话判断预算；托管按整次运行累计（含子任务）。不自动替换模型。Claude 可使用上报 USD 费用 × 汇率；Codex 请填写实际模型标识和单价。未知价格显示未计价，托管模式会转人工。</p><div class="usage-fields"><label>模型标识<input name="model" placeholder="与客户端遥测完全一致"></label>${[['input','普通输入'],['output','输出'],['cached','缓存读取'],['creation','缓存写入']].map(([k,l])=>`<label>${l}（元 / 百万 Token）<input name="${k}" type="number" min="0" step="any" placeholder="${k==='creation'?'无写入计费填 0':'按供应商价格填写'}"></label>`).join('')}</div><button class="button primary" type="submit" ${createPending?'disabled':''}>创建连接</button></form>`}
function renderReceipts(root){const box=root?.querySelector('#coding-receipts');if(!root?.isConnected||!box)return;box.innerHTML=pendingSetups.map(c=>`<div class="note">${esc(c.name)} 已创建。密钥仅在本页内存中，刷新前请保存。 <button class="button" data-new-setup="${c.id}">查看新连接密钥</button></div>`).join('');box.querySelectorAll('[data-new-setup]').forEach(b=>b.onclick=()=>{const c=pendingSetups.find(c=>c.id===b.dataset.newSetup);if(c){setup(c,c.token);renderReceipts(root)}})}
function setup(c,token){if(token)pendingSetups=pendingSetups.filter(x=>x.id!==c.id);const origin=globalThis.location?.origin||'http://127.0.0.1:8080';const endpoint=origin+'/api/telemetry/'+c.id+'/v1/logs';const commands=c.source==='claude-code'?`export CLAUDE_CODE_ENABLE_TELEMETRY=1\nexport OTEL_LOGS_EXPORTER=otlp\nexport OTEL_METRICS_EXPORTER=none\nexport OTEL_EXPORTER_OTLP_LOGS_PROTOCOL=http/protobuf\nexport OTEL_EXPORTER_OTLP_LOGS_ENDPOINT='${endpoint}'\nexport OTEL_EXPORTER_OTLP_LOGS_HEADERS="Authorization=Bearer $AG_CONNECTION_TOKEN"\nclaude`:`# 在用户级 ~/.codex/config.toml 设置；不要放入项目配置\n[otel]\nlog_user_prompt = false\nexporter = { otlp-http = { endpoint = "${endpoint}", protocol = "binary", headers = { Authorization = "\${AG_OTEL_AUTH}" } } }\n# 启动前在 shell 设置：export AG_OTEL_AUTH="Bearer $AG_CONNECTION_TOKEN"`;
 const run=`export AG_URL='${origin}'\n# 在终端安全设置 AG_CONNECTION_TOKEN（下方一次性连接密钥）\nnode scripts/guard-run.mjs --connection ${c.id} -- ${c.source==='codex'?'codex exec':'claude -p'} "实现一个小功能"`;
 const dialog=openDialog(`<h2>${esc(c.name)} · 接入配置</h2>${token?`<div class="note">连接密钥只展示一次。仅可写此连接遥测、查询本连接决策。请保存到本机环境变量。</div><label>连接密钥<input readonly type="password" value="${esc(token)}" id="coding-secret"></label><button class="button" data-secret-copy>复制连接密钥</button><span id="copy-status" role="status"></span>`:'<p>连接密钥不会回显；丢失后请撤销旧连接并重新创建。</p>'}<p>${c.mode==='managed'?'需要 macOS / Linux 本机启动器。被停止后需人工检查和重新启动，不自动重放任务。':'只监测连接不会停止客户端。环境变量需在启动客户端的终端或用户级配置设置。'}</p><pre class="coding-code">${esc(c.mode==='managed'?run:commands)}</pre><p class="usage-caption">默认不采集对话正文。工具参数只用于服务器内存中的签名计算，不存储原文；Claude 默认不发送参数，可选开启 OTEL_LOG_TOOL_DETAILS=1 提升循环检测覆盖。不同版本的父子事件可能不完整。</p><a class="button" href="CODING.html" target="_blank" rel="noopener">完整部署与历史导入说明 ↗</a>`);if(token){const status=dialog.querySelector('#copy-status'),secret=dialog.querySelector('#coding-secret');dialog.querySelector('[data-secret-copy]').onclick=async()=>{try{await navigator.clipboard.writeText(token);if(ownsDialog(status))status.textContent='已复制'}catch{if(ownsDialog(status)){secret.type='text';secret.focus();secret.select?.();status.textContent='剪贴板不可用，密钥已显示，请选中复制并妥善保管。'}}}}
}
function confirmAction(root,id,action){const ticket=epoch;const dialog=openDialog(`<h2>${action==='stop'?'请求停止此连接的任务':'撤销此连接'}</h2><p>${action==='stop'?'服务端将禁止继续运行；在线启动器收到决策后终止自己创建的进程。离线客户端无法确认停止。':'旧凭证将无法继续写入遥测，历史记录保留。只监测模式不会停止客户端。'}</p><button class="button primary" data-confirm-action>确认</button><div role="status" id="action-error"></div>`);const b=dialog.querySelector('[data-confirm-action]'),error=dialog.querySelector('#action-error');b.onclick=async()=>{if(b.disabled)return;b.disabled=true;try{await api('/api/coding/connections/'+id+'/'+action,{});if(ticket!==epoch||!root.isConnected)return;if(ownsDialog(b))closeDialog();mount(root)}catch(e){if(ownsDialog(error))error.textContent=e.message}finally{b.disabled=false}}}
async function detail(root,ticket,id){const detailTicket=++detailEpoch;const box=root.querySelector('#coding-detail'),c=connections.find(c=>c.id===id);box.innerHTML='<div class="empty">正在读取活动…</div>';try{const d=await api('/api/coding/events?'+new URLSearchParams({connection_id:id,offset,limit:50}));if(ticket!==epoch||detailTicket!==detailEpoch||selected!==id||!root.isConnected)return;box.innerHTML=`<div class="section-title">${esc(c.name)} / 活动与覆盖</div><p class="usage-caption">${c.tasks.reduce((s,t)=>s+t.unknown_cost,0)} 次费用未知；${c.tasks.reduce((s,t)=>s+t.missing_arguments,0)} 次工具调用缺少参数，未参与循环判断。子智能体统计仅覆盖可识别的父子关联或已完成子任务。</p>${c.tasks.map(t=>`<section class="card coding-task"><div class="coding-card-head"><strong>${esc(t.id)}</strong><span>${c.mode==='monitor'?'只监测':t.status==='stopped'?'停止决策已生效':t.status==='approval'?'等待人工确认':t.status==='success'?'启动器正常退出':'任务状态：'+esc(t.status)}</span></div><p>估算 ${amount(t.cost)} / 预算 ${amount(t.budget)} · ${t.children} 个已识别子任务</p>${t.alerts.slice(-5).map(a=>`<div class="coding-alert"><strong>${esc(a.title)}</strong><span>${esc(a.detail)}</span><small>${a.action==='notify'?'仅告警':a.action==='approve'?'需人工确认':'请求停止'} · ${esc(a.at)}</small></div>`).join('')}${t.status==='approval'&&c.mode==='managed'&&canManage?`<form data-coding-approve="${t.id}" class="usage-fields"><label>追加预算（元）<input type="number" name="extra" min="0.001" step="any" required></label><button class="button" type="submit">批准后手动重启</button><button class="button" type="button" data-coding-reject="${t.id}">拒绝并停止</button></form>`:''}</section>`).join('')}<section class="card table-wrap"><table><thead><tr><th>时间 / 会话</th><th>活动</th><th>模型 / 工具</th><th>输入 / 输出 Token</th><th>费用</th><th>检测覆盖</th></tr></thead><tbody>${d.rows.map(e=>`<tr><td>${esc(new Date(e.at).toLocaleString('zh-CN'))}<small>${esc(e.session_id)}</small></td><td>${kind[e.kind]||esc(e.kind)}${e.error?' · 失败':''}</td><td>${esc(e.model)}<small>${esc(e.tool)}</small></td><td>${e.input_tokens??'—'} / ${e.output_tokens??'—'}</td><td>${e.basis==='unpriced'?'未计价':e.basis==='not_billable'?'—':amount(e.cost)}<small>${e.basis==='telemetry_estimate'?'上报估算':e.basis==='rate_estimate'?'单价估算':''}</small></td><td>${e.loop_coverage==='arguments_hash'?'参数签名可用':e.loop_coverage==='missing_arguments'?'缺少参数':e.child_coverage==='spawn_result'?'创建结果 ID':e.child_coverage==='start_hook'?'启动钩子':e.child_coverage==='completed_only'?'仅完成事件':e.child_coverage==='parent_link'?'父子关联可用':'—'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">尚无遥测。完成本机配置并运行一个任务后刷新。</td></tr>'}</tbody></table></section><div class="usage-pagination"><span>${d.total} 条 · ${d.rows.length?offset+1:0}–${offset+d.rows.length}</span><button class="button" data-coding-prev ${offset===0?'disabled':''}>上一页</button><button class="button" data-coding-next ${offset+d.rows.length>=d.total?'disabled':''}>下一页</button></div>${c.mode==='monitor'&&canManage?'<details class="card coding-create"><summary>导入历史 OTLP JSON（管理员）</summary><p>仅导入你选择的日志文件，不扫描本机目录。重复导入不会重复记账，历史数据不会触发实时停止。</p><input type="file" accept=".json,application/json" id="coding-file"><button class="button" data-coding-import>导入所选文件</button></details>':''}`;
 box.querySelector('[data-coding-prev]').onclick=()=>{offset=Math.max(0,offset-50);detail(root,ticket,id)};box.querySelector('[data-coding-next]').onclick=()=>{offset+=50;detail(root,ticket,id)};
 for(const f of box.querySelectorAll('[data-coding-approve]'))f.onsubmit=async e=>{e.preventDefault();await change(()=>api('/api/tasks/'+f.dataset.codingApprove+'/approve',{approved:true,extraBudget:Number(new FormData(f).get('extra'))}),root,f)};
 for(const b of box.querySelectorAll('[data-coding-reject]'))b.onclick=()=>change(()=>api('/api/tasks/'+b.dataset.codingReject+'/approve',{approved:false}),root,b);
 const importer=box.querySelector('[data-coding-import]');if(importer)importer.onclick=async()=>{if(importer.disabled)return;importer.disabled=true;try{const file=box.querySelector('#coding-file').files?.[0];if(!file||file.size>1048576)throw Error('请选择不超过 1 MB 的 OTLP JSON 文件');const payload=JSON.parse(await file.text());if(ticket!==epoch||selected!==id||!root.isConnected)return;const result=await api('/api/coding/connections/'+id+'/import',payload);if(ticket!==epoch||selected!==id||!root.isConnected)return;await detail(root,ticket,id);if(ticket!==epoch||selected!==id||!root.isConnected)return;root.querySelector('#coding-message').textContent=`导入 ${result.accepted} 条，跳过重复 ${result.duplicates} 条，不支持 ${result.ignored} 条，无效 ${result.rejected} 条。`}catch(e){if(ticket===epoch&&root.isConnected)root.querySelector('#coding-message').textContent=e.message}finally{importer.disabled=false}};
 }catch(e){if(ticket===epoch&&detailTicket===detailEpoch&&selected===id)box.innerHTML='<div class="empty">'+esc(e.message)+'</div>'}}
async function change(fn,root,control){if(control.dataset.pending==='1')return;const form=control.closest('form')||control;if(form.dataset.pending==='1')return;form.dataset.pending='1';const buttons=form.matches('button')?[form]:[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);const ticket=epoch;try{await fn();if(ticket===epoch&&root.isConnected)mount(root)}catch(e){if(ticket===epoch&&root.isConnected)root.querySelector('#coding-message').textContent=e.message}finally{delete form.dataset.pending;buttons.forEach(b=>b.disabled=false)}}
